  "option" TEXT NOT NULL,
  "lineage" TEXT NOT NULL,
  "source_node" TEXT NOT NULL,
  "target_node" TEXT NOT NULL,
  "source" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, resolution) REFERENCES resolution_case (tenant, id),
  FOREIGN KEY (tenant, choice) REFERENCES resolution_choice (tenant, id),
  FOREIGN KEY (tenant, canonical) REFERENCES canonical_record (tenant, id),
  FOREIGN KEY (tenant, decision) REFERENCES decision_case (tenant, id),
  FOREIGN KEY (tenant, outcome) REFERENCES decision_outcome (tenant, id),
  FOREIGN KEY (tenant, terminal) REFERENCES decision_event (tenant, id),
  FOREIGN KEY (tenant, option) REFERENCES decision_option (tenant, id),
  FOREIGN KEY (tenant, lineage) REFERENCES lineage_relation (tenant, id),
  FOREIGN KEY (tenant, source_node) REFERENCES lineage_node (tenant, id),
  FOREIGN KEY (tenant, target_node) REFERENCES lineage_node (tenant, id),
  FOREIGN KEY (tenant, source) REFERENCES source_record (tenant, id)
);

CREATE TABLE participation (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "participation_set" TEXT NOT NULL,
  "participant" TEXT NOT NULL,
  "role" TEXT NOT NULL,
  "valid_from" TEXT NOT NULL,
  "valid_until" TEXT,
  "recorded_by" TEXT NOT NULL,
  "reason" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, participation_set) REFERENCES participation_set (tenant, id),
  FOREIGN KEY (tenant, participant) REFERENCES party (tenant, id),
  FOREIGN KEY (tenant, role) REFERENCES participation_role (tenant, id)
);

CREATE TABLE participation_end (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "participation" TEXT NOT NULL,
  "effective_at" TEXT NOT NULL,
  "revoked" INTEGER NOT NULL,
  "recorded_by" TEXT NOT NULL,
  "reason" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, participation) REFERENCES participation (tenant, id)
);

CREATE TABLE participation_role (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "namespace" TEXT NOT NULL,
  "name" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id)
);

CREATE TABLE participation_set (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "label" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id)
);

CREATE TABLE party (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "label" TEXT NOT NULL,
  "identifiers" TEXT,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, identifiers) REFERENCES identifier_set (tenant, id)
);

CREATE TABLE principal_representation (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "party" TEXT NOT NULL,
  "principal" TEXT NOT NULL,
  "valid_from" TEXT NOT NULL,
  "valid_until" TEXT,
  "recorded_by" TEXT NOT NULL,
  "reason" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, party) REFERENCES party (tenant, id)
);

CREATE TABLE representation_revocation (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "representation" TEXT NOT NULL,
  "effective_at" TEXT NOT NULL,
  "recorded_by" TEXT NOT NULL,
  "reason" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, representation) REFERENCES principal_representation (tenant, id)
);

CREATE TABLE desired_revision (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "scope" TEXT NOT NULL,
  "sequence" INTEGER NOT NULL,
  "pin" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, scope) REFERENCES reconciliation_scope (tenant, id),
  FOREIGN KEY (tenant, pin) REFERENCES specification_pin (tenant, id)
);

CREATE TABLE drift (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "observation" TEXT NOT NULL,
  "desired" TEXT NOT NULL,
  "pin" TEXT NOT NULL,
  "anchor" TEXT NOT NULL,
  "field" TEXT NOT NULL,
  "explanation" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, observation) REFERENCES observation (tenant, id),
  FOREIGN KEY (tenant, desired) REFERENCES desired_revision (tenant, id),
  FOREIGN KEY (tenant, pin) REFERENCES specification_pin (tenant, id)
);

CREATE TABLE observation (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "desired" TEXT NOT NULL,
  "run" TEXT NOT NULL,
  "finish" TEXT NOT NULL,
  "support" TEXT NOT NULL,
  "observed_at" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, desired) REFERENCES desired_revision (tenant, id),
  FOREIGN KEY (tenant, run) REFERENCES evaluation_run (tenant, id),
  FOREIGN KEY (tenant, finish) REFERENCES evaluation_finish (tenant, id),
  FOREIGN KEY (tenant, support) REFERENCES evidence_seal (tenant, id)
);

CREATE TABLE reconciliation_attempt (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "desired" TEXT NOT NULL,
  "observation" TEXT NOT NULL,
  "fulfillment" TEXT NOT NULL,
  "key_" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, desired) REFERENCES desired_revision (tenant, id),
  FOREIGN KEY (tenant, observation) REFERENCES observation (tenant, id),
  FOREIGN KEY (tenant, fulfillment) REFERENCES fulfillment (tenant, id)
);

CREATE TABLE reconciliation_event (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "scope" TEXT NOT NULL,
  "ordinal" INTEGER NOT NULL,
  "previous" TEXT,
  "desired" TEXT NOT NULL,
  "desired_sequence" INTEGER NOT NULL,
  "kind" TEXT NOT NULL,
  "attempt" TEXT,
  "result" TEXT,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, scope) REFERENCES reconciliation_scope (tenant, id),
  FOREIGN KEY (tenant, previous) REFERENCES reconciliation_event (tenant, id),
  FOREIGN KEY (tenant, desired) REFERENCES desired_revision (tenant, id),
  FOREIGN KEY (tenant, attempt) REFERENCES reconciliation_attempt (tenant, id),
  FOREIGN KEY (tenant, result) REFERENCES reconciliation_result (tenant, id)
);

CREATE TABLE reconciliation_result (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "attempt" TEXT NOT NULL,
  "desired" TEXT NOT NULL,
  "outcome" TEXT NOT NULL,
  "support" TEXT NOT NULL,
  "detail" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, attempt) REFERENCES reconciliation_attempt (tenant, id),
  FOREIGN KEY (tenant, desired) REFERENCES desired_revision (tenant, id),
  FOREIGN KEY (tenant, support) REFERENCES evidence_seal (tenant, id)
);

CREATE TABLE reconciliation_scope (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "key_" TEXT NOT NULL,
  PRIMARY KEY (tenant, id)
);

CREATE TABLE realization (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "pin" TEXT NOT NULL,
  "build_hash" TEXT NOT NULL,
  "manifest_digest" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, pin) REFERENCES specification_pin (tenant, id)
);

CREATE TABLE repository (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "key_" TEXT NOT NULL,
  "provider" TEXT NOT NULL,
  "locator" TEXT NOT NULL,
  "version" INTEGER NOT NULL,
  PRIMARY KEY (tenant, id)
);

CREATE TABLE specification_pin (
  "tenant" TEXT NOT NULL,
  "id" TEXT NOT NULL,
  "repository" TEXT NOT NULL,
  "anchor" TEXT NOT NULL,
  "revision" TEXT NOT NULL,
  PRIMARY KEY (tenant, id),
  FOREIGN KEY (tenant, repository) REFERENCES repository (tenant, id)
);

